parameters.body:
={
  "model": "claude-sonnet-4-6",
  "max_tokens": 1000,
  "temperature": 0.2,
  "system": "You are a fashion product classifier. Analyze the provided garment image and return ONLY valid JSON, no prose, no markdown fences.\n\nDetect and output:\n- category: Topwear | Bottomwear | Dress | Outerwear | Innerwear | Activewear | Loungewear | Ethnic | Accessories | Footwear\n- subcategory: specific type (e.g. T-Shirt, Polo, Shirt, Jeans, Chinos, Joggers, Shorts, Kurta, Frock, Hoodie, Sweatshirt, Jacket, Skirt, Co-ord Set)\n- garment_type: descriptive label combining cut + style (e.g. \"oversized graphic t-shirt\")\n- gender: Men | Women | Boys | Girls\n- age_group: Adult | Kids (4-7) | Kids (8-12) | Teen\n- confidence: float 0.0-1.0\n\nOutput schema:\n{\"category\":\"\",\"subcategory\":\"\",\"garment_type\":\"\",\"gender\":\"\",\"age_group\":\"\",\"confidence\":0.0}",
  "messages": [{
    "role": "user",
    "content": [
      {"type": "image", "source": {"type": "url", "url": "={{ $node[\"Webhook\"].json.body.image_url }}"}},
      {"type": "text", "text": "={{ \"Client gender hint: \" + $node[\"Webhook\"].json.body.gender_hint }}"}
    ]
  }]
}

parameters.jsCode:
const presetMap = {
  'Men':   'adult male model, age 25-32, athletic-lean build, short dark hair, clean-shaven or light stubble, neutral confident expression',
  'Women': 'adult female model, age 22-30, slim build, shoulder-length hair, minimal makeup, neutral pleasant expression',
  'Boys':  'young male child model, age 8-11, average build, neat short hair, friendly neutral expression',
  'Girls': 'young female child model, age 8-11, average build, neat shoulder-length hair, friendly neutral expression'
};
const sharedBase = "Professional e-commerce studio photograph. STRICT FULL BODY SHOT — entire model visible from the top of the head to the soles of the feet, with comfortable margin above the head and below the feet. No cropping of head, hair, hands, or feet. Square 1:1 framing. Plain seamless backdrop in soft cream / off-white / warm-white tone. Soft diffused even studio lighting, no harsh shadows, no color cast on the garment. Photorealistic, sharp focus on the garment, accurate color reproduction, natural skin tone, high resolution catalog quality. The garment must match the reference image exactly — same color, pattern, cut, fabric texture, stitching, and all design details. No logos or text added that are not in the reference. No accessories added.";

const raw = $node['Claude - B1 Classify'].json.content.find(b => b.type === 'text').text;
const classification = JSON.parse(raw.replace(/```json|```/g, '').trim());
const preset = presetMap[classification.gender] || presetMap['Men'];
const hostedUrl = $node['imgbb - Host Image'].json.data.url;

const frontPrompt = `${preset} wearing the exact garment from the reference image. STRICT FULL BODY SHOT, head to toe, entire body visible including full head and both feet, model centered in frame, facing camera directly, neutral standing pose, feet shoulder-width apart, arms relaxed naturally at sides. Eyes looking at camera. ${sharedBase}`;
const sidePrompt  = `Same model and same garment as the front shot — preserve identity, skin tone, hair, and garment exactly. STRICT FULL BODY SHOT in 90-degree side profile, head to toe, entire body visible including full head and both feet, model turned to their left so the camera sees their right side, natural relaxed standing pose, arms at sides, head facing forward in profile. Focus on garment silhouette, drape, and fit from the side. ${sharedBase}`;
const backPrompt  = `Same model and same garment as the front and side shots — preserve identity and garment exactly. STRICT FULL BODY back view, head to toe, entire body visible including full head and both feet, model facing directly away from camera, natural standing pose, arms relaxed at sides. Focus on rear garment design, back graphics or prints, stitching, yoke, hood, and overall rear fit. ${sharedBase}`;

return [{ json: {
  classification,
  model_preset: preset,
  front_prompt: frontPrompt,
  side_prompt:  sidePrompt,
  back_prompt:  backPrompt,
  hosted_image_url: hostedUrl,
  raw_image_url: $node['Webhook'].json.body.image_url,
  gender_hint: $node['Webhook'].json.body.gender_hint
}}];

const prev = $node['Code - Parse B1'].json;
const extractUrl = (node) => {
  const j = node.json;
  return j?.results?.[0]?.url || j?.image_url || j?.data?.url || j?.url || '';
};
return [{ json: {
  ...prev,
  front_image_url: extractUrl($node['HF - Generate Front']),
  side_image_url:  extractUrl($node['HF - Generate Side']),
  back_image_url:  extractUrl($node['HF - Generate Back'])
}}];

const raw = $node['Claude - B2 Attributes'].json.content.find(b => b.type === 'text').text;
const attributes = JSON.parse(raw.replace(/```json|```/g, '').trim());
return [{ json: { ...($node['Code - Store Image URLs'].json), attributes } }];

const raw = $node['Claude - B3 Title Desc'].json.content.find(b => b.type === 'text').text;
const content = JSON.parse(raw.replace(/```json|```/g, '').trim());
return [{ json: { ...($node['Code - Parse B2'].json), content } }];

const raw = $node['Claude - B4 Variants'].json.content.find(b => b.type === 'text').text;
const variants = JSON.parse(raw.replace(/```json|```/g, '').trim());
return [{ json: { ...($node['Code - Parse B3'].json), variants } }];

const raw = $node['Claude - B5 SEO'].json.content.find(b => b.type === 'text').text;
const seo = JSON.parse(raw.replace(/```json|```/g, '').trim());
return [{ json: { ...($node['Code - Parse B4'].json), seo } }];

const raw = $node['Claude - B6 Final'].json.content.find(b => b.type === 'text').text;
const product = JSON.parse(raw.replace(/```json|```/g, '').trim());
const prev = $node['Code - Parse B5'].json;
product.product_id  = product.product_id  || ('PRD-' + Date.now());
product.created_at  = product.created_at  || new Date().toISOString();
product.source_image = prev.raw_image_url;
product.images = {
  front: prev.front_image_url,
  side:  prev.side_image_url,
  back:  prev.back_image_url
};
return [{ json: {
  filename: `product_${product.product_id}.json`,
  content:  JSON.stringify(product, null, 2),
  product
}}];
